export function SolutionPieceGrid(
  props: {
    widthPx: number;
    cols: number;
    rows: number;
    pieces: {
      [puzName: string]: {
        x: number;
        y: number;
        colspan?: number;
        rowspan?: number;
        rotate?: number;
        flip?: boolean;
      };
    };
  } & HTMLProps<HTMLDivElement>
) {
  const rounds = useAccessibleRounds();
  const puzzles = useAccessiblePuzzles();
  if (rounds === null || puzzles === null) return <Spinner />;

  const { widthPx, cols, rows, pieces, style = {}, ...otherProps } = props;
  const pieceViews = Object.entries(pieces).map(([puzName, piece]) => {
    const puzData = puzzles[puzName];
    if (puzData === undefined) return null;
    const { x, y, colspan = 1, rowspan = 1, rotate = 0, flip = false } = piece;
    const pieceCols =
      puzData.cols ??
      (puzData.roundId === undefined
        ? null
        : rounds[puzData.roundId]?.pieceCols) ??
      1;
    return (
      <PuzzleLink key={puzName} puzName={puzName} subpage="piece">
        <div
          className={clsObj({
            "piece-view": true,
            "piece-view-transparent": !!puzData.transparentBackground,
          })}
          style={{
            left: `${(100 * x) / cols}%`,
            top: `${(100 * y) / rows}%`,
            width: `${(100 * colspan) / cols}%`,
            height: `${(100 * rowspan) / rows}%`,
            rotate: `${rotate}deg`,
            scale: flip ? "-1 1" : undefined,
          }}
        >
          <PuzzleContentDisplay
            puzName={puzName}
            fontSize={`${(BASE_FONT_SIZE_PX / pieceCols) * (widthPx / BASE_OUTER_WRAPPER_WIDTH_PX) * (colspan / cols) * (FONT_SIZE_SCALING_PER_ROUND[puzData.roundId ?? ""] ?? 1)}px`}
          />
        </div>
      </PuzzleLink>
    );
  });
  return (
    <div
      style={{
        aspectRatio: `${cols} / ${rows}`,
        maxWidth: widthPx,
        margin: "1em auto",
        position: "relative",
        ...style,
      }}
      {...otherProps}
    >
      {pieceViews}
    </div>
  );
}

export function ImageSubmission(props: {
  isLocked: boolean;
  slot: SubmitImageSlot;
  supportedMimeTypes: string[];
  maxFileSize: number;
  onSubmitSuccess: () => Promise<void>;
}) {
  const { isLocked, slot, supportedMimeTypes, maxFileSize, onSubmitSuccess } =
    props;
  const [fileErr, setFileErr] = useState<string | null>(null);
  const sockClient = useSockClient();
  const uploadLock = useUILock();

  return (
    <div className="image-submission">
      <div>
        <input
          type="file"
          disabled={isLocked || uploadLock.isHeld}
          onChange={(e) => {
            if (e.target.files === null) return;
            const [file] = e.target.files;
            if (file === undefined) return;
            if (!supportedMimeTypes.includes(file.type)) {
              setFileErr("File format not supported.");
              return;
            }
            if (file.size > maxFileSize) {
              setFileErr("File is too large.");
              return;
            }
            uploadLock.acquireAndRun(async (getIsCanceled) => {
              try {
                await sockClient.sendDirectBackendReqAsync(
                  {
                    type: DirectBackendReqType.SUBMIT_IMAGE,
                    payload: { slot },
                  },
                  file,
                  () =>
                    new Promise((resolve, reject) => {
                      const reader = new FileReader();
                      reader.onload = (e) => {
                        const url = e.target?.result;
                        if (typeof url !== "string") {
                          reject(new Error("failed to read file"));
                          return;
                        }
                        resolve(url);
                      };
                      reader.onerror = (e) => {
                        reject(e.target?.error);
                      };
                      reader.readAsDataURL(file);
                    })
                );
                await onSubmitSuccess();
                setFileErr(null);
              } catch (err) {
                setFileErr(
                  "Failed to upload image. Please try again later and contact us if the problem persists."
                );
                console.error(err);
              }
            });
          }}
        />
      </div>
      {uploadLock.isHeld ? (
        <Spinner inline />
      ) : fileErr === null ? null : (
        <div className="image-submission-error">{fileErr}</div>
      )}
    </div>
  );
}
